select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Re:amaze AI Agent', 'Chatwoot Captain', 'Chatfuel AI Agent', 'Wati Astra', 'respond.io AI Agents', 'Kombai', 'Builder.io Fusion', 'Macroscope', 'Dialzara', 'Tembo') order by e.name;
